import { useState, useEffect } from 'react';

export const useUrlQueryParams = () => {
  const [queryParams, setInternalQueryParams] = useState(
    new URLSearchParams(typeof window !== 'undefined' ? window.location.search : '')
  );

  useEffect(() => {
    const handlePopState = () => {
      setInternalQueryParams(new URLSearchParams(window.location.search));
    };

    if (typeof window !== 'undefined') {
      window.addEventListener('popstate', handlePopState);
    }

    return () => {
      if (typeof window !== 'undefined') {
        window.removeEventListener('popstate', handlePopState);
      }
    };
  }, []);

  const getQueryParams = () => {
    return queryParams;
  };

  const setQueryParams = (params: Record<string, string | string[] | undefined>) => {
    if (typeof window !== 'undefined') {
      const currentParams = new URLSearchParams(queryParams.toString());
      for (const key in params) {
        const value = params[key];
        if (value === undefined || value === '') {
          currentParams.delete(key);
        } else if (Array.isArray(value)) {
          currentParams.delete(key);
          value.forEach((val) => currentParams.append(key, val));
        } else {
          currentParams.set(key, value);
        }
      }
      const newUrl = `${window.location.pathname}?${currentParams.toString()}${window.location.hash}`;
      window.history.replaceState({}, '', newUrl);
      setInternalQueryParams(currentParams);
    }
  };

  return { getQueryParams, setQueryParams };
};
