import type { RefObject } from 'react';
import { useState, useEffect } from 'react';
import { FaArrowUp } from 'react-icons/fa6';
import { Button } from '../ui/button';
import { Icon } from '../ui/icon';
import { Box } from 'styled-system/jsx';

interface ScrollToTopButtonProps<E extends HTMLElement> {
  scrollContainerRef: RefObject<E | null>;
}

export function ScrollToTopButton<E extends HTMLElement>({
  scrollContainerRef
}: ScrollToTopButtonProps<E>) {
  const [isVisible, setIsVisible] = useState(false);

  const toggleVisibility = () => {
    if (scrollContainerRef.current && scrollContainerRef.current.scrollTop > 300) {
      setIsVisible(true);
    } else {
      setIsVisible(false);
    }
  };

  const scrollToTop = () => {
    scrollContainerRef.current?.scrollTo({
      top: 0,
      behavior: 'smooth'
    });
  };

  useEffect(() => {
    const scrollContainer = scrollContainerRef.current;
    if (scrollContainer) {
      scrollContainer.addEventListener('scroll', toggleVisibility);
    }
    return () => {
      if (scrollContainer) {
        scrollContainer.removeEventListener('scroll', toggleVisibility);
      }
    };
  }, [scrollContainerRef]);

  return (
    <Box
      data-disabled={!isVisible ? 'true' : undefined}
      zIndex="1000"
      position="fixed"
      right="4"
      bottom="4"
      opacity={{ base: 1, _disabled: 0 }}
      transition="opacity 0.3s ease-in-out"
      pointerEvents={{ base: 'auto', _disabled: 'none' }}
    >
      <Button
        variant="outline"
        size="lg"
        aria-label="Scroll to top"
        onClick={scrollToTop}
        borderRadius="full"
        boxShadow="lg"
        _hover={{ bgColor: 'colorPalette.default' }}
      >
        <Icon asChild>
          <FaArrowUp />
        </Icon>
      </Button>
    </Box>
  );
}
