import { useQueryClient } from '@tanstack/react-query';
import { useTranslation } from 'react-i18next';
import { InfiniteTweetScroll } from '~/components/bluebird/InfiniteTweetScroll';
import { Box, Stack } from 'styled-system/jsx';
import { Text } from '~/components/ui/text';
import { Button } from '~/components/ui/button';
import { useBluebirdAuthors } from '~/hooks/useBluebirdAuthors';
import { useBluebirdMonthsYears } from '~/hooks/useBluebirdMonthsYears';
import { useUrlQueryParams } from '~/utils/url';
import MainContentAndRightSidebar from '~/components/layout/MainContentAndRightSidebar';

export default function Page() {
  const { getQueryParams, setQueryParams } = useUrlQueryParams();
  const selectedMonthYear = getQueryParams().get('monthYear') || undefined;

  const queryClient = useQueryClient();
  const { t, i18n } = useTranslation();

  const { data: authors = [] } = useBluebirdAuthors();

  const { data: monthsYears = [] } = useBluebirdMonthsYears();

  const handleMonthYearClick = (monthYear: string) => {
    setQueryParams({ monthYear: monthYear === selectedMonthYear ? undefined : monthYear });
    queryClient.invalidateQueries({ queryKey: ['tweets'] });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <MainContentAndRightSidebar
      rightSidebarContent={({ close }) => {
        return (
          <Box p="4">
            <Text mb="2" fontWeight="bold">
              {t('bluebird.filterByMonthYear')}
            </Text>
            <Stack gap="2">
              {monthsYears.map((my) => (
                <Button
                  key={my.monthYear}
                  variant="ghost"
                  size="lg"
                  onClick={() => {
                    handleMonthYearClick(my.monthYear);
                    close();
                  }}
                  data-active={selectedMonthYear === my.monthYear ? 'true' : undefined}
                  justifyContent="flex-start"
                  width="full"
                  _active={{ bg: 'bg.emphasized' }}
                  _hover={{ bg: 'bg.emphasized' }}
                >
                  {new Date(my.monthYear).toLocaleString(i18n.language, {
                    month: 'long',
                    year: 'numeric'
                  })}{' '}
                  <Text as="span" color="fg.subtle" fontSize="sm">
                    ({my.count})
                  </Text>
                </Button>
              ))}
            </Stack>
          </Box>
        );
      }}
    >
      <InfiniteTweetScroll
        authors={authors}
        selectedMonthYear={selectedMonthYear}
        monthsYears={monthsYears}
        onMonthYearClick={handleMonthYearClick}
      />
    </MainContentAndRightSidebar>
  );
}
