import { useVirtualizer } from '@tanstack/react-virtual';
import { useRef, useEffect } from 'react';
import { useInfiniteQuery, useQueryClient } from '@tanstack/react-query';
import { Tweet } from './Tweet';
import { LoadingIndicator } from './LoadingIndicator';
import { PostInputArea } from './PostInputArea';
import { Box } from 'styled-system/jsx';
import type { Author, DBTweet } from '~/types/bluebird';
import { ScrollToTopButton } from '~/components/utils/ScrollToTopButton';
import { useUrlQueryParams } from '~/utils/url';

import type { MonthYearCount } from '~/hooks/useBluebirdMonthsYears';

interface InfiniteTweetScrollProps {
  authors: Author[];
  selectedMonthYear?: string;
  monthsYears: MonthYearCount[];
  onMonthYearClick: (monthYear: string) => void;
}

const getTweets = async ({
  pageParam = 0,
  currentSearchTerm,
  selectedCharacterFilters,
  selectedMonthYear
}: {
  pageParam?: number;
  currentSearchTerm: string;
  selectedCharacterFilters: string[];
  selectedMonthYear?: string;
}): Promise<{ tweets: DBTweet[]; nextOffset: number | undefined }> => {
  const limit = 20;
  let url = `/api/bluebird/tweets?limit=${limit}&offset=${pageParam}`;
  if (currentSearchTerm) {
    url += `&q=${encodeURIComponent(currentSearchTerm)}`;
  }
  if (selectedCharacterFilters.length > 0) {
    url += `&authorId=${encodeURIComponent(selectedCharacterFilters.join(','))}`;
  }
  if (selectedMonthYear) {
    url += `&monthYear=${encodeURIComponent(selectedMonthYear)}&sortBy=createdAt&order=asc`;
  }

  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }
  const fetchedTweets: DBTweet[] = await response.json();
  const nextOffset = fetchedTweets.length < limit ? undefined : pageParam + fetchedTweets.length;
  return { tweets: fetchedTweets, nextOffset };
};

export function InfiniteTweetScroll({
  authors,
  selectedMonthYear,
  monthsYears,
  onMonthYearClick
}: InfiniteTweetScrollProps) {
  // eslint-disable-next-line react-compiler/react-compiler
  'use no memo';

  const { getQueryParams, setQueryParams } = useUrlQueryParams();

  const currentSearchTerm = getQueryParams().get('q') || '';
  const selectedCharacterFilters = getQueryParams().getAll('authorId');

  const queryClient = useQueryClient();

  const {
    data,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
    isLoading: isLoadingTweets,
    isError: _isErrorTweets
  } = useInfiniteQuery({
    queryKey: ['tweets', currentSearchTerm, selectedCharacterFilters, selectedMonthYear],
    queryFn: ({ pageParam }) =>
      getTweets({ pageParam, currentSearchTerm, selectedCharacterFilters, selectedMonthYear }),
    initialPageParam: 0,
    getNextPageParam: (lastPage) => lastPage.nextOffset
  });

  const tweets = data?.pages.flatMap((page) => page.tweets) || [];
  const isLoading = isLoadingTweets || isFetchingNextPage;
  const hasMore = hasNextPage;

  const handleSearch = (searchTerm: string) => {
    setQueryParams({ q: searchTerm });
    queryClient.invalidateQueries({ queryKey: ['tweets'] });
  };

  const handleCharacterFilterChange = (authorId: string) => {
    const newFilters = selectedCharacterFilters.includes(authorId)
      ? selectedCharacterFilters.filter((id) => id !== authorId)
      : [...selectedCharacterFilters, authorId];
    setQueryParams({ authorId: newFilters });
    queryClient.invalidateQueries({ queryKey: ['tweets'] });
  };

  const parentRef = useRef<HTMLDivElement>(null);

  const virtualizer = useVirtualizer({
    count: tweets.length + 1,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 250, // Estimate average item size
    overscan: 5
  });

  const virtualItems = virtualizer.getVirtualItems();

  useEffect(() => {
    const [lastItem] = [...virtualizer.getVirtualItems()].reverse();

    if (!lastItem) {
      return;
    }

    if (lastItem.index >= tweets.length - 1 && hasNextPage && !isFetchingNextPage) {
      fetchNextPage();
    }
  }, [
    hasNextPage,
    fetchNextPage,
    tweets.length,
    isFetchingNextPage,
    virtualizer.getVirtualItems()
  ]);

  return (
    <Box ref={parentRef} height="calc(100vh - 64px)" overflowY="auto">
      <PostInputArea
        onSearch={handleSearch}
        authors={authors}
        selectedCharacterFilters={selectedCharacterFilters}
        onCharacterFilterChange={handleCharacterFilterChange}
        searchTerm={currentSearchTerm}
      />
      <Box style={{ height: `${virtualizer.getTotalSize()}px` }} position="relative">
        {virtualItems.map((virtualItem) => {
          const isLoaderRow = virtualItem.index > tweets.length - 1;
          const tweet = tweets[virtualItem.index];

          return (
            <Box
              key={virtualItem.key}
              data-index={virtualItem.index}
              ref={virtualizer.measureElement}
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                transform: `translateY(${virtualItem.start}px)`
              }}
            >
              {isLoaderRow ? (
                <LoadingIndicator
                  isLoading={isLoading}
                  hasMore={hasMore}
                  onIntersect={() => {
                    // if (!isLoading && hasMore) {
                    //   fetchNextPage();
                    // }
                  }}
                  selectedMonthYear={selectedMonthYear}
                  monthsYears={[...monthsYears].reverse()}
                  onMonthYearClick={onMonthYearClick}
                />
              ) : (
                <Tweet tweet={tweet.data} />
              )}
            </Box>
          );
        })}
      </Box>
      <ScrollToTopButton scrollContainerRef={parentRef} />
    </Box>
  );
}
