import React from 'react';
import { Button } from '../ui/button';
import { Textarea } from '../ui/textarea';
import { Box, HStack, Stack, styled } from 'styled-system/jsx';
import type { Author } from '~/types/bluebird';

interface PostInputAreaProps {
  onSearch: (searchTerm: string) => void;
  authors: Author[];
  selectedCharacterFilters: string[];
  onCharacterFilterChange: (authorId: string) => void;
  searchTerm: string;
}

export function PostInputArea({
  onSearch,
  authors,
  selectedCharacterFilters,
  onCharacterFilterChange,
  searchTerm
}: PostInputAreaProps) {
  const handleApplyFilters = () => {
    onSearch(searchTerm);
  };

  const handleKeyPress = (event: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.key === 'Enter') {
      onSearch(searchTerm);
    }
  };

  return (
    <Stack borderBottomWidth="1px" borderColor="border.default" p="4" bg="bg.subtle">
      <HStack alignItems="flex-start">
        <HStack gap="2" alignItems="center" mb="3">
          <Box borderRadius="full" w="12" h="12" p="2" bg="white">
            <img
              src="https://www.lovelive-anime.jp/lovehigh/img/koushou.png"
              alt="Poster"
              className="object-contain"
            />
          </Box>
        </HStack>
        <Stack flex="1">
          <Textarea
            id="searchInput"
            placeholder="Search posts..."
            value={searchTerm}
            onChange={(e) => onSearch(e.target.value)}
            onKeyDown={handleKeyPress}
            flexGrow="1"
            borderColor="border.subtle"
            borderRadius="md"
            borderWidth="1px"
            p="2"
            _focus={{ outline: 'none', ring: '2' }}
          />
        </Stack>
        <HStack gap="2" alignItems="center" mb="3">
          <Box display="flex" gap="2" flexDirection={{ base: 'column', sm: 'row' }}>
            <Button
              id="applyFilters"
              onClick={handleApplyFilters}
              colorPalette="accent"
              borderRadius="md"
              p="2"
              _focus={{ outline: 'none', ring: '2' }}
            >
              Search
            </Button>
          </Box>
        </HStack>
      </HStack>
      <HStack gap="2" justifyContent="center" mb="3" flexWrap="wrap">
        {authors.map((author) => (
          <styled.button key={author.id} onClick={() => onCharacterFilterChange(author.id)}>
            <styled.img
              src={
                author.profilePicture?.replace('normal', '400x400') ||
                'https://via.placeholder.com/48'
              }
              alt={author.name}
              title={author.name}
              data-character-id={author.id}
              data-active={selectedCharacterFilters.includes(author.id) ? 'true' : undefined}
              cursor="pointer"
              objectFit="cover"
              borderColor={{ base: 'transparent', _active: 'colorPalette.default' }}
              borderRadius="full"
              borderWidth="2px"
              w="10"
              h="10"
              transitionDuration="200ms"
              transitionProperty="all"
            />
          </styled.button>
        ))}
      </HStack>
    </Stack>
  );
}
